      sec5Tip = "Coalescing ('stick together') collisions preserve momentum ONLY—kinetic energy is lost as heat/sound!",
      misc1 = MisconceptionAnalysis("Action and reaction cancel out so nothing can ever accelerate.", "Equal and opposite sounds like +F − F = 0.", "Action pushes Body B while Reaction pushes Body A—they act on separate objects so Body B still accelerates.", "Draw separate free-body diagrams for each colliding body."),
      misc2 = MisconceptionAnalysis("Kinetic energy is conserved in every collision.", "Conservation of momentum gets confused with KE.", "Momentum is always conserved in isolated collisions, but Kinetic Energy is ONLY conserved in perfectly elastic collisions.", "Treat 'stick together' as inelastic unless told otherwise."),
      guidedPrompt = "A uniform 100 cm metre rule weighing 1.2 N balances horizontally on a knife-edge at the 40 cm mark when a mass M hangs at the 15 cm mark. Calculate the weight of M.",
      guidedHints = listOf(
