      cheatOverview = "F = Δp/Δt; ΣF = 0 and ΣMoments = 0 for complete equilibrium.",
      cheatLegend = listOf("p = mv", "J = Ft", "τ = Fd⊥", "N_lift = m(g±a)"),
      cheatTraps = listOf("Forgetting uniform bar weight acts at midpoint", "Adding opposite velocities without minus sign", "Assuming KE is conserved in sticking collisions"),
      cheatMemory = "CW = ACW around the fulcrum; Up = Down.",
