      misc1 = MisconceptionAnalysis("Friction reduces both Mechanical Advantage and Velocity Ratio.", "Both sound like machine ratings.", "Friction forces you to pull with larger Effort E, reducing MA = L/E, whereas VR = dE/dL depends purely on rigid geometry!", "VR stays unchanged unless you rebuild the gears, pulleys, or ramp angle."),
      misc2 = MisconceptionAnalysis("Holding a heavy 50 kg bag stationary for 10 minutes performs huge physics work.", "Your muscles feel exhausted.", "Biology burns chemical calories, but because displacement s = 0, mechanical work W = F×0 = 0 J.", "No displacement along force = zero mechanical work."),
