      projModel = "Useful output = 800×1.5 = 1200 J. Ramp ideal force = 1200/6 = 200 N; with friction say 280 N total effort → work in = 280×6 = 1680 J → η = 1200/1680 = 71.4%. Ramp slashes required peak muscle force by 65%.",
      cheatOverview = "MA = L/E, VR = dE/dL, η = MA/VR × 100%; W = Fd cos θ.",
