      vocab = listOf(
        VocabularyEntry("Specific Heat Capacity (c)", "Heat energy required to warm 1 kg of a substance by 1 K (J kg⁻¹ K⁻¹).", "Thermal stubbornness: water's 4200 means it warms slowly.", "Total heat capacity C = mc applies to the whole object, not per kg."),
        VocabularyEntry("Specific Latent Heat (L)", "Heat absorbed or released per kg during phase change at CONSTANT temperature.", "Hidden energy breaking bonds without raising thermometer readings.", "Lf (melting, 3.36×10⁵ J/kg ice) vs Lv (boiling, 2.26×10⁶ J/kg steam)."),
        VocabularyEntry("Relative Humidity", "Percentage ratio of actual water vapour mass present to max saturation vapour at that temperature.", "How muggy the air feels compared to 100% rain-ready air.", "Drops when warm air rises above dew point without adding moisture."),
