      intel2 = "WAEC Paper 2 checks electrical method Pt = mcΔθ + h and cooling correction.",
      recap1 = "Flat plateaus on heating curves prove latent heat absorption at steady temperature.",
      recap2 = "Land/sea breezes work via water's massive specific heat capacity (4200 J/kg·K) and convection.",
      sec3Title = "3. Evaporation vs Boiling, SVP & Heat Transfer Modes",
      sec3Body = "Evaporation escapes strictly from the surface at ANY temperature and cools the leftover liquid because fastest energetic molecules leave first. Conduction passes heat by lattice/electron collisions (metals best); Convection relies on warm fluid expansion rising; Radiation needs zero medium (sunlight through space vacuum).",
      sec3Formula = "Q = mc\\Delta\\theta + mL   |   P t = mc\\Delta\\theta   |   RH = \\frac{\\text{SVP at Dew Point}}{\\text{SVP at Room T}}\\times 100\\%",
      sec3Tip = "Pressure cookers trap steam to raise boiling point above 100°C, cooking beans much faster!",
      sec3Mech = "Black dull surfaces absorb AND emit thermal radiation fastest; shiny polished surfaces reflect both.",
      sec3Intel = "NECO/JAMB love asking why clay pots cool drinking water in hot Nigerian markets (porous evaporation).",
      sec3Recap = "Evaporation cools at all temperatures; boiling erupts throughout at SVP = atmospheric P.",
      sec4Title = "4. Nigerian Clay Water Pots, Dew Point & Generator Radiators",
      sec4Body = "Northern Nigerian clay pots ('randa') seep tiny water films through microscopic pores; dry Harmattan air evaporates this outer film, extracting latent heat from the pot and chilling water naturally without electricity. Water circulates in generator radiators because 4200 J/(kg·K) absorbs huge engine waste heat smoothly.",
      sec4Tip = "Wind and low humidity speed evaporation dramatically.",
      sec5Title = "5. Calorimetry Mixture Balance Protocol",
      sec5Body = "Always write: Heat Lost by hot bodies = Heat Gained by cold liquid + Heat Gained by calorimeter cup! Check units carefully (all g or all kg; don't mix c = 4.2 J/g·K with m in kg).",
      sec5Tip = "100°C steam burns far worse than 100°C boiling water because steam dumps an extra 2.26×10⁶ J/kg of Lv!",
      misc1 = MisconceptionAnalysis("Temperature keeps rising while ice melts or water boils.", "Heat continues flowing in.", " thermometers freeze at 0°C (melting) and 100°C (boiling) because added heat breaks intermolecular bonds instead of speeding molecules.", "Always split ice-to-water problems into separate Δθ and latent steps."),
      misc2 = MisconceptionAnalysis("Silvered flask walls prevent conduction.", "Metals look shiny.", "Vacuum prevents conduction & convection; shiny silver blocks RADIATION.", "Match flask part to exact heat mode blocked."),
      guidedPrompt = "A 1500 W electric kettle heats 0.5 kg of water initially at 20°C to 100°C. Assuming 80% heater efficiency (c_water = 4200 J/kg·K), find the time required.",
      guidedHints = listOf(
        "Hint 1: Heat needed Q = m c Δθ = 0.5 × 4200 × (100 − 20).",
        "Hint 2: Effective heating power P_useful = 0.80 × 1500 W = 1200 W.",
        "Hint 3: Time t = Q / P_useful.",
