      cheatOverview = "Q = mcΔθ (warming) | Q = mL (flat phase change); Heat Lost = Heat Gained.",
      cheatLegend = listOf("c_water = 4200 J/kg·K", "Lf_ice = 3.36e5 J/kg", "Lv_steam = 2.26e6 J/kg", "V = Pt"),
      cheatTraps = listOf("Mixing grams with J/kg·K", "Assuming T rises during boiling", "Forgetting calorimeter vessel m_c c_c Δθ"),
