    "phys_10_waves_sound" to spec(
      prereq = listOf("phys_06_shm_circular (frequency f & period T)"),
      dep = "Wave interference, standing harmonics, and speed formulas extend straight into Light Optics, Doppler shifts, and Photon energy E = hf.",
      vocab = listOf(
        VocabularyEntry("Transverse vs Longitudinal", "Particles vibrate perpendicular vs parallel to wave travel direction.", "Rope shake (up-down) vs slinky push-pull compressions.", "Sound is longitudinal ONLY (cannot be polarized); EM waves are transverse."),
        VocabularyEntry("Progressive Wave Equation", "y = A sin(2πx/λ − 2πft) showing displacement along x and t.", "Formula snapshot encoding Amplitude A, wavelength λ, and frequency f.", "Match ω = 2πf and k = 2π/λ directly to extract speed v = ω/k."),
        VocabularyEntry("Standing Wave Node", "Fixed zero-displacement point formed by destructive interference.", "Quiet spot halfway between vibrating antinodes.", "Node-to-next-Node spacing is ALWAYS λ/2 (half wavelength, not full!)."),
        VocabularyEntry("Beat Frequency", "Throbbing loudness pulse rate f_beat = |f₁ − f₂| between two slightly mismatched tones.", "Wobble heard when two guitar strings are nearly in tune.", "Used by musicians to tune instruments to exact unison."),
      ),
      mech1 = "Wave speed v = fλ depends on the MEDIUM (string tension/mass or air temperature), whereas frequency f is locked by the vibrating source; crossing boundaries changes λ while keeping f constant!",
      mech2 = "Closed-bottom pipes force a Node at the sealed bottom and Antinode at the open top (L = λ/4), permitting ONLY odd harmonics (1st, 3rd, 5th) compared to all harmonics (1, 2, 3...) in open pipes.",
      intel1 = "JAMB tests reading v and λ from y = A sin(kx − ωt), closed vs open fundamental ratio (1 : 2), and sonar echo 2d = vt.",
      intel2 = "WAEC Paper 2 checks end-correction resonance tube calculations L₂ − L₁ = λ/2.",
      recap1 = "Frequency comes from source; speed comes from medium; wavelength adjusts to keep v = fλ.",
      recap2 = "Closed pipe: L = λ/4 (odd harmonics only); Open pipe: L = λ/2 (all harmonics).",
      sec3Title = "3. Reflection, Refraction, Diffraction & Polarization Test",
      sec3Body = "All waves reflect, refract, diffract around obstacles (strongest when gap ≈ λ), and interfere. ONLY transverse waves (light, radio, stretched strings) can be Polarized through slits/polaroids; longitudinal waves (sound) fail polarization because particles oscillate along the travel axis.",
      sec3Formula = "v = f\\lambda   |   f_{\\text{closed}} = \\frac{v}{4L}   |   f_{\\text{open}} = \\frac{v}{2L}   |   2d = vt",
      sec3Tip = "In resonance tubes, subtract L₂ − L₁ = λ/2 to eliminate unknown end correction c automatically!",
      sec3Mech = "Because λ_sound ≈ 0.5–1 m matches doorways while λ_light ≈ 500 nm is tiny, sound bends cleanly around open classroom doors while light casts sharp shadows.",
      sec3Intel = "JAMB loves asking which wave property proves light is transverse → Polarization!",
      sec3Recap = "Polarization = exclusive proof of transverse oscillation.",
      sec4Title = "4. Talking Drum Tension Tuning & Sonar Bathymetry",
      sec4Body = "Yoruba talking drummers ('gangan') squeeze leather tension cords under their arm to tighten drumhead tension T—raising wave speed and pitch instantly because f ∝ √T! Nigerian hydrographic vessels map harbour channels using sonar echoes with 2d = vt.",
      sec4Tip = "Echo questions MUST use 2d = vt (there AND back!).",
      sec5Title = "5. Node Spacing & Echo Factor Checks",
      sec5Body = "Check two classic traps: (1) adjacent Node-to-Node is λ/2, whereas Node-to-Antinode is λ/4; (2) when reading y = A sin(2πft − 2πx/λ), inspect whether 2π is already factored outside the brackets before picking f and λ.",
      sec5Tip = "Fundamental closed pipe wavelength is 4L (twice longer wavelength → half the pitch of an open pipe!).",
      misc1 = MisconceptionAnalysis("Increasing wave frequency makes waves travel faster through air.", "v = fλ looks like v grows with f.", "Air sound speed (~340 m/s) depends only on air temperature/medium; raising f shrinks λ proportionally so speed stays unchanged.", "Hold v constant within the same uniform medium."),
      misc2 = MisconceptionAnalysis("Distance between two consecutive nodes is one full wavelength λ.", "Peaks look one full cycle apart.", "A standing wave fits TWO loops inside one full λ, so Node-to-Node is λ/2.", "Double the Node-to-Node distance to get λ."),
      guidedPrompt = "A student standing 85 m from a tall cliff shouts and hears the echo 0.50 s later. Using this speed of sound, find the fundamental frequency of a closed organ pipe 0.50 m long (ignore end correction).",
      guidedHints = listOf(
        "Hint 1 (Echo Speed): Remember sound travels 2 × 85 m = 170 m in 0.50 s.",
        "Hint 2: v = 170 / 0.50 = 340 m/s.",
        "Hint 3 (Closed Pipe): Fundamental f₀ = v / (4L) = 340 / (4 × 0.50).",
      ),
      guidedApproach = "2d = vt → find v → closed pipe fundamental v/(4L).",
      guidedSolution = "v = (2 × 85) / 0.50 = 340 m/s. Closed pipe f₀ = 340 / (4 × 0.50) = 170 Hz.",
      projTitle = "Classroom Acoustic Resonance & Echo Calibration Guide",
      projScenario = "Design a safe resonance-tube experiment to measure room-temperature sound speed without knowing end correction c.",
      projStages = listOf("Select tuning fork of known 512 Hz frequency.", "Measure first (L₁) and second (L₂) loud water column depths.", "Compute λ = 2(L₂ − L₁) and v = fλ."),
      projRubric = listOf("Eliminates end correction via L₂ − L₁.", "Multiplies difference by 2 accurately.", "Computes realistic ~340 m/s speed."),
      projModel = "Holding 512 Hz fork above water tube gives resonance at L₁ ≈ 16.0 cm and L₂ ≈ 49.2 cm. Eliminating end correction: λ = 2(49.2 − 16.0) = 66.4 cm = 0.664 m → v = 512 × 0.664 = 340.0 m/s.",
      cheatOverview = "v = fλ; N-N = λ/2; Closed pipe L=λ/4 (odd only); Open pipe L=λ/2 (all).",
      cheatLegend = listOf("v = fλ", "Echo: 2d = vt", "f_closed = v/4L", "f_open = v/2L", "Beat = |f₁−f₂|"),
      cheatTraps = listOf("Forgetting factor 2 in echoes", "Using N-N = λ instead of λ/2", "Allowing even harmonics in closed pipes"),
      cheatMemory = "Closed Pipe = Quarter (4L) Odd; Open Pipe = Half (2L) All.",
    ),
    "phys_11_optics_lenses" to spec(
      prereq = listOf("phys_10_waves_sound (wave refraction)"),
      dep = "Optics links wave refraction to telescope/microscope design, eye accommodation (Biology link), and electromagnetic spectra.",
      vocab = listOf(
        VocabularyEntry("Refractive Index (n)", "Ratio sin i / sin r or speed c_vac / v_medium.", "How strongly glass or water bends and slows light.", "High n means slower light and smaller critical angle C."),
        VocabularyEntry("Total Internal Reflection", "Complete reflection inside denser medium when angle exceeds critical C (sin C = 1/n).", "Perfect mirror bounce inside fibre-optic glass without silver paint.", "Requires BOTH: dense→rare travel AND i > C."),
        VocabularyEntry("Real vs Virtual Image", "Real images project onto screens (inverted); Virtual cannot be projected (upright).", "Movie screen image (real) vs bathroom mirror face (virtual).", "Converging lenses form virtual magnifiers ONLY when u < f!"),
        VocabularyEntry("Lens Power (D)", "Reciprocal of focal length strictly in METRES (P = 1/f in dioptres).", "Prescription glass strength (+ converging, − diverging).", "Divide by f in metres—NEVER leave f in centimetres!"),
      ),
      mech1 = "Refraction happens because the edge of a wavefront hitting glass slows down first while the other side keeps running fast in air, pivoting the beam toward the normal.",
      mech2 = "In lens/mirror equation 1/f = 1/u + 1/v ('Real is Positive'), real objects and real focused images carry + signs, while virtual images and diverging focal lengths carry − signs.",
      intel1 = "JAMB tests 1/f = 1/u + 1/v magnification m = v/u, critical angle sin C = 1/n, and Myopia vs Hypermetropia lenses.",
      intel2 = "WAEC Paper 2 checks clean ray diagrams (parallel→focus, centre→undeviated) and apparent depth n = real / apparent.",
      recap1 = "TIR requires Dense→Rare + angle i > Critical Angle C.",
      recap2 = "Real-is-positive: diverging f is negative; virtual image v is negative.",
      sec3Title = "3. Mirrors, Optical Instruments & Human Eye Defects",
      sec3Body = "Concave mirrors focus parallel rays at f (makeup/headlight reflectors); convex mirrors always form diminished upright wide-view images (car side mirrors). In human vision, Myopia (eyeball too long, focuses before retina) requires a DIVERGING (−) lens; Hypermetropia (focuses behind retina) requires a CONVERGING (+) lens.",
      sec3Formula = "\\frac{1}{f} = \\frac{1}{u} + \\frac{1}{v}   |   m = \\frac{v}{u}   |   n = \\frac{\\sin i}{\\sin r} = \\frac{\\text{Real Depth}}{\\text{Apparent Depth}} = \\frac{1}{\\sin C}",
      sec3Tip = "In normal adjustment of an astronomical telescope, length = f_o + f_e and angular magnification = f_o / f_e!",
      sec3Mech = "For compound microscopes, objective builds a magnified real image inside the eyepiece's focal length, which the eyepiece magnifies further.",
      sec3Intel = "NECO/JAMB frequently swap Myopia (diverging/concave) vs Hypermetropia (converging/convex).",
      sec3Recap = "Short-sighted (near OK, far blurry) = Concave (−); Long-sighted = Convex (+).",
      sec4Title = "4. Submarine Fibre-Optic Internet Cables & Solar Concentration",
      sec4Body = "Nigeria's submarine internet cables landing at Lekki and Victoria Island guide laser pulses across thousands of kilometres of ocean floor using Total Internal Reflection inside ultra-pure glass cores wrapped by lower-index cladding. Curved mirrors also concentrate sunlight for rural solar cookers.",
      sec4Tip = "Fibre optics require core refractive index n₁ > cladding refractive index n₂.",
      sec5Title = "5. Sign-Convention & Unit Traps",
      sec5Body = "Two recurring optics errors: (1) plugging f = 20 cm into P = 1/f gives 0.05 instead of +5.0 D (convert 20 cm → 0.20 m first!); (2) forgetting diverging lenses and convex mirrors always take NEGATIVE f in 1/f = 1/u + 1/v.",
      sec5Tip = "Number of images in two plane mirrors at angle θ: N = (360°/θ) − 1.",
      misc1 = MisconceptionAnalysis("Total internal reflection happens when light speeds from air into glass.", "Light bounces off windows.", "TIR is IMPOSSIBLE moving from low-n air into high-n glass; it ONLY happens inside dense glass/water trying to exit to rarer air above critical angle C.", "Always check Dense → Rare first."),
      misc2 = MisconceptionAnalysis("Convex lenses always produce real inverted images.", "Projectors form real images.", "When object sits INSIDE focal length (u < f), a convex lens acts as a magnifying glass producing an upright virtual image!", "Check u vs f before predicting real/virtual."),
      guidedPrompt = "An object stands 15 cm in front of a diverging lens of focal length 10 cm. Locate the image distance v, state its nature, and calculate magnification.",
      guidedHints = listOf(
        "Hint 1 (Sign): Diverging lens → f = −10 cm; real object → u = +15 cm.",
        "Hint 2: 1/v = 1/f − 1/u = −1/10 − 1/15 = −5/30.",
        "Hint 3: Invert v = −6.0 cm (virtual, same side, upright) and m = |v|/u.",
      ),
      guidedApproach = "Assign f = −10 cm → solve 1/v → interpret negative sign as virtual upright.",
      guidedSolution = "1/v = −1/10 − 1/15 = −5/30 → v = −6.0 cm (virtual, upright, 6.0 cm in front of lens). Magnification m = 6/15 = 0.40.",
      projTitle = "Optometry Screening & Optical Fibre Diagnostic Brief",
      projScenario = "A school eye-screening camp finds a student can see clearly only up to 1.0 m (cannot read blackboard at far end). Prescribe the exact corrective lens power in Dioptres.",
      projStages = listOf("Identify defect (Myopia).", "Set object at infinity u = ∞ and desired virtual image at far point v = −1.0 m.", "Compute focal length f and power P = 1/f."),
      projRubric = listOf("Diagnoses Myopia accurately.", "Uses v = −1.0 m.", "Computes f = −1.0 m, P = −1.0 D diverging lens."),
      projModel = "Student is Myopic (far point 1.0 m < ∞). Lens must map distant u = ∞ to virtual image at v = −1.0 m: 1/f = 1/∞ + 1/(−1.0) → f = −1.0 m → Power P = −1.0 D (diverging/concave glass).",
      cheatOverview = "1/f = 1/u + 1/v; sin C = 1/n (Dense→Rare); Power D = 1/f(m).",
      cheatLegend = listOf("f < 0 diverging", "v < 0 virtual", "m = v/u", "n = c/v = real/app"),
      cheatTraps = listOf("Forgetting minus sign on diverging f", "Computing Lens Power in cm instead of metres", "Applying TIR from air into glass"),
      cheatMemory = "MYopia = MY minus (−) lens; Hyper = Plus (+).",
    ),
    "phys_12_electrostatics_capacitors" to spec(
      prereq = listOf("phys_02_vectors (force directions)", "phys_05_work_machines (energy U)"),
      dep = "Electric potential V and charge Q move directly into DC Current Electricity (I = Q/t) and Semiconductors.",
      vocab = listOf(
        VocabularyEntry("Coulomb's Law", "Electrostatic force F = k q₁q₂ / r² between point charges.", "Gravity-like inverse-square pull/push between charges.", "Doubling separation r cuts force to ¼!"),
        VocabularyEntry("Electric Potential (V)", "Work done bringing +1 C from infinity to that point (V = kq/r).", "Electrical height (Joules per Coulomb).", "Scalar quantity—add potentials algebraically with signs!"),
        VocabularyEntry("Capacitance (C)", "Charge stored per unit volt across plates (C = Q/V in Farads).", "Tank capacity for static electric charge.", "C = ε₀A/d grows with wider plates A and tighter gap d."),
        VocabularyEntry("Dielectric", "Insulating filler between capacitor plates raising capacitance by factor εᵣ.", "Electric sponge polarizing inside the gap to store extra charge.", "Always increases C compared to vacuum/air."),
      ),
      mech1 = "Like charges repel and unlike charges attract along the line joining them; inside a hollow charged metal conductor, E-field is ZERO because charges push outward to the outer skin.",
      mech2 = "In PARALLEL capacitors share the exact same voltage V, so total stored charge adds (C_p = C₁ + C₂); in SERIES they hold identical charge Q while voltages split (1/C_s = 1/C₁ + 1/C₂).",
      intel1 = "JAMB tests inverse-square Coulomb scaling, series/parallel C_total, and stored energy ½CV² = ½QV = Q²/(2C).",
      intel2 = "WAEC Paper 2 checks lightning conductor pointed-action physics and gold-leaf electroscope charging by induction.",
      recap1 = "Capacitor network rules are the EXACT OPPOSITE of resistor rules!",
      recap2 = "E-field inside hollow metal shell is zero; sharp points concentrate charge density.",
      sec3Title = "3. Charging by Induction, Lightning Arrestors & Energy Forms",
      sec3Body = "To charge an electroscope positively by induction, bring a NEGATIVE rod near (don't touch), touch earth briefly so negative electrons flee to Earth, release earth BEFORE pulling the rod away—leaving net positive charge! Sharp copper spikes on building lightning rods ionize nearby air quietly via high charge density at tips.",
      sec3Formula = "F = \\frac{q_1 q_2}{4\\pi\\varepsilon_0 r^2}   |   C = \\frac{\\varepsilon A}{d}   |   U = \\frac{1}{2}CV^2 = \\frac{Q^2}{2C}",
      sec3Tip = "When disconnecting earth during induction, ALWAYS remove the Earth wire FIRST before pulling away the inducing rod!",
      sec3Mech = "Charging a capacitor raises voltage steadily from 0 to V, giving average voltage ½V so work stored is ½QV, not full QV.",
      sec3Intel = "NECO/WAEC commonly ask why stored energy is ½QV instead of QV.",
      sec3Recap = "Three equivalent energy formulas: ½CV² = ½QV = Q²/(2C).",
      sec4Title = "4. Harmattan Static Shocks, Surge Arrestors & Flash Capacitors",
      sec4Body = "During dry northern Harmattan weather, walking across synthetic rugs separates electrons cleanly—producing sparks on metal door handles because dry air lacks conductive moisture. Phone cameras discharge capacitors rapidly in milliseconds to fire bright LED/Xenon flashes.",
      sec4Tip = "Humid rainy-season air leaks static charge quietly so static shocks drop sharply.",
      sec5Title = "5. Capacitor Series/Parallel & Microfarad Traps",
      sec5Body = "Always double-check prefixes: 1 μF = 10⁻⁶ F, 1 nF = 10⁻⁹ F, 1 pF = 10⁻¹² F. Never add capacitors in series directly like resistors; invert 1/C_s = 1/C₁ + 1/C₂ then flip back!",
      sec5Tip = "Removing a battery leaves Q constant; keeping battery plugged in keeps V constant if a dielectric slides in.",
      misc1 = MisconceptionAnalysis("Series capacitors add as C₁ + C₂ just like series resistors.", "Series always adds in student habits.", "Series capacitors share charge Q with voltages summing V₁+V₂, forcing 1/C_eq = 1/C₁ + 1/C₂ (smaller than smallest!).", "Capacitors: Parallel = Add; Series = Reciprocal."),
      misc2 = MisconceptionAnalysis("Charging by induction gives the electroscope the SAME charge sign as the rod.", "Contact gives same sign.", "Contact transfers same sign; Induction leaves the OPPOSITE sign because opposite charge is attracted and earth drains the repelled same-sign charge.", "Induction = Opposite; Contact = Same."),
      guidedPrompt = "A 4 μF capacitor and a 12 μF capacitor are connected in series across a 24 V battery. Find equivalent capacitance, charge on each capacitor, and total stored energy.",
      guidedHints = listOf(
        "Hint 1: Series → 1/C_eq = 1/4 + 1/12 = 4/12 → C_eq = 3 μF.",
        "Hint 2: Total charge Q = C_eq × V = 3 μF × 24 V = 72 μC (identical on both!).",
        "Hint 3: Energy U = ½ × C_eq × V² (convert μF = 10⁻⁶ F!).",
      ),
      guidedApproach = "Reciprocal sum → Q = C_eq V → ½C_eq V² in Joules.",
      guidedSolution = "C_eq = (4×12)/(4+12) = 3.0 μF. Q = 3.0×10⁻⁶ × 24 = 7.2×10⁻⁵ C (72 μC on each). U = 0.5 × 3×10⁻⁶ × 24² = 8.64×10⁻⁴ J.",
      projTitle = "Lightning Protection & Surge Arrestor Engineering Check",
      projScenario = "Explain to a school principal why a pointed copper lightning conductor bolted to a thick copper earth strip protects tall science laboratories.",
      projStages = listOf("Explain charge induction under negatively charged storm clouds.", "Describe point discharge ('corona wind') neutralizing cloud charge.", "Explain safe low-resistance earthing path."),
      projRubric = listOf("Mentions sharp tip high charge density.", "Explains quiet ion neutralization.", "Specifies buried copper earthing plate."),
      projModel = "Storm clouds induce strong positive charge on the sharp copper spikes, creating intense E-field that strips air electrons cleanly—sending positive ions upward to neutralize the cloud gently or channeling any direct strike safely straight into moist soil.",
      cheatOverview = "F = kq₁q₂/r²; C_p = C₁+C₂; 1/C_s = 1/C₁+1/C₂; U = ½CV².",
      cheatLegend = listOf("1 μF = 10⁻⁶ F", "E = F/q = V/d", "Q = CV", "C = εA/d"),
      cheatTraps = listOf("Adding series capacitors directly", "Forgetting 10⁻⁶ for μF in Joules", "Pulling inducing rod before disconnecting earth"),
      cheatMemory = "Capacitors flip Resistors: Parallel Sums, Series Shrinks.",
    ),
    "phys_13_circuits_emf" to spec(
